trait FK[F[_],G[_]] { self => def apply[A](a:F[A]):G[A];def compose[E[_]](f:FK[E,F]):FK[E,G]=new FK[E,G] { def apply[A](a:E[A]):G[A]=self(f(a)) } }; object Main { def main(args:Array[String]):Unit={val f=new FK[List,Option] { def apply[A](a:List[A]):Option[A]=a.headOption };val g=new FK[Option,List] { def apply[A](a:Option[A]):List[A]=a.toList };println(f.compose(g)(Some(3):Option[Int]))} }
